import sys

def parse_time(h, m):
    return h * 60 + m

def format_time(minutes):
    h = minutes // 60
    m = minutes % 60
    return h, m

def find_earliest_takeoff(n, s, landings):
    current_time = 0
    for i in range(n):
        landing_time = parse_time(landings[i][0], landings[i][1])
        if landing_time - current_time >= s + 1:
            return format_time(current_time)
        current_time = landing_time + 1
    return format_time(current_time)

